alter table game_players add column if not exists pvp_trophies integer not null default 1000,add column if not exists pvp_tickets integer not null default 5,add column if not exists pvp_wins integer not null default 0,add column if not exists pvp_losses integer not null default 0,add column if not exists pvp_banned boolean not null default false;
alter table player_heroes add column if not exists hero_template_id text,add column if not exists base_atk numeric,add column if not exists base_hp numeric,add column if not exists attack_growth numeric,add column if not exists hp_growth numeric,add column if not exists bonus_atk numeric not null default 0,add column if not exists bonus_hp numeric not null default 0,add column if not exists final_atk numeric,add column if not exists final_hp numeric,add column if not exists archetype text,add column if not exists stats_seed text,add column if not exists stats_generated_at timestamptz;

create or replace function pvp_stat_unit(v text) returns numeric language sql immutable as $$select (abs(hashtextextended(v,0))%1000000)::numeric/999999$$;
create or replace function public.ensure_pvp_hero_stats() returns trigger language plpgsql set search_path=public as $$declare r text;seed text;min_atk numeric;max_atk numeric;min_hp numeric;max_hp numeric;min_ag numeric;max_ag numeric;min_hg numeric;max_hg numeric;atk_mult numeric:=1;hp_mult numeric:=1;kinds text[]:=array['warrior','assassin','tank','mage','archer','support'];begin r:=normalize_hero_rarity(new.rarity);new.hero_template_id:=coalesce(new.hero_template_id,new.hero_key,new.name);seed:=coalesce(new.stats_seed,new.id::text||':'||new.hero_template_id||':'||new.user_id::text||':'||new.created_at::text);new.stats_seed:=seed;new.archetype:=coalesce(new.archetype,kinds[1+(abs(hashtextextended(seed||':kind',0))%6)::int]);select * into min_atk,max_atk,min_hp,max_hp,min_ag,max_ag,min_hg,max_hg from(values('common',80,110,800,1100,.025,.030,.040,.045),('uncommon',105,140,1050,1400,.028,.033,.042,.048),('rare',135,180,1350,1800,.031,.036,.045,.051),('epic',175,235,1750,2350,.034,.039,.048,.054),('legendary',230,310,2300,3100,.037,.042,.051,.057))s(rarity,min_atk,max_atk,min_hp,max_hp,min_ag,max_ag,min_hg,max_hg) where rarity=r;case new.archetype when 'warrior' then hp_mult:=1.15;when 'assassin' then atk_mult:=1.15;hp_mult:=.9;when 'tank' then atk_mult:=.85;hp_mult:=1.3;when 'mage' then atk_mult:=1.2;hp_mult:=.85;when 'archer' then atk_mult:=1.1;when 'support' then atk_mult:=.9;hp_mult:=1.1;else new.archetype:='warrior';hp_mult:=1.15;end case;if new.base_atk is null then new.base_atk:=greatest(1,round((min_atk+pvp_stat_unit(seed||':atk')*(max_atk-min_atk))*atk_mult));end if;if new.base_hp is null then new.base_hp:=greatest(1,round((min_hp+pvp_stat_unit(seed||':hp')*(max_hp-min_hp))*hp_mult));end if;if new.attack_growth is null then new.attack_growth:=round(min_ag+pvp_stat_unit(seed||':ag')*(max_ag-min_ag),5);end if;if new.hp_growth is null then new.hp_growth:=round(min_hg+pvp_stat_unit(seed||':hg')*(max_hg-min_hg),5);end if;new.level:=greatest(1,coalesce(new.level,1));new.final_atk:=greatest(1,round((new.base_atk+coalesce(new.bonus_atk,0))*power(1+new.attack_growth,new.level-1)));new.final_hp:=greatest(1,round((new.base_hp+coalesce(new.bonus_hp,0))*power(1+new.hp_growth,new.level-1)));new.stats_generated_at:=coalesce(new.stats_generated_at,now());return new;end$$;
create or replace function public.ensure_pvp_hero_stats() returns trigger language plpgsql set search_path=public as $$
declare r text;seed text;min_atk numeric;max_atk numeric;min_hp numeric;max_hp numeric;min_ag numeric;max_ag numeric;min_hg numeric;max_hg numeric;atk_mult numeric:=1;hp_mult numeric:=1;kinds text[]:=array['warrior','assassin','tank','mage','archer','support'];
begin
 r:=normalize_hero_rarity(new.rarity);new.hero_template_id:=coalesce(new.hero_template_id,new.hero_key,new.name);seed:=coalesce(new.stats_seed,new.id::text||':'||new.hero_template_id||':'||new.user_id::text||':'||new.created_at::text);new.stats_seed:=seed;new.archetype:=coalesce(new.archetype,kinds[1+(abs(hashtextextended(seed||':kind',0))%6)::int]);
 select s.min_atk,s.max_atk,s.min_hp,s.max_hp,s.min_ag,s.max_ag,s.min_hg,s.max_hg into min_atk,max_atk,min_hp,max_hp,min_ag,max_ag,min_hg,max_hg from(values('common',80,110,800,1100,.025,.030,.040,.045),('uncommon',105,140,1050,1400,.028,.033,.042,.048),('rare',135,180,1350,1800,.031,.036,.045,.051),('epic',175,235,1750,2350,.034,.039,.048,.054),('legendary',230,310,2300,3100,.037,.042,.051,.057))s(rarity,min_atk,max_atk,min_hp,max_hp,min_ag,max_ag,min_hg,max_hg)where rarity=r;
 case new.archetype when'warrior'then hp_mult:=1.15;when'assassin'then atk_mult:=1.15;hp_mult:=.9;when'tank'then atk_mult:=.85;hp_mult:=1.3;when'mage'then atk_mult:=1.2;hp_mult:=.85;when'archer'then atk_mult:=1.1;when'support'then atk_mult:=.9;hp_mult:=1.1;else new.archetype:='warrior';hp_mult:=1.15;end case;
 if new.base_atk is null then new.base_atk:=greatest(1,round((min_atk+pvp_stat_unit(seed||':atk')*(max_atk-min_atk))*atk_mult));end if;if new.base_hp is null then new.base_hp:=greatest(1,round((min_hp+pvp_stat_unit(seed||':hp')*(max_hp-min_hp))*hp_mult));end if;if new.attack_growth is null then new.attack_growth:=round(min_ag+pvp_stat_unit(seed||':ag')*(max_ag-min_ag),5);end if;if new.hp_growth is null then new.hp_growth:=round(min_hg+pvp_stat_unit(seed||':hg')*(max_hg-min_hg),5);end if;new.level:=greatest(1,coalesce(new.level,1));new.final_atk:=greatest(1,round((new.base_atk+coalesce(new.bonus_atk,0))*power(1+new.attack_growth,new.level-1)));new.final_hp:=greatest(1,round((new.base_hp+coalesce(new.bonus_hp,0))*power(1+new.hp_growth,new.level-1)));new.stats_generated_at:=coalesce(new.stats_generated_at,now());return new;
end$$;
drop trigger if exists player_heroes_pvp_stats on player_heroes;create trigger player_heroes_pvp_stats before insert or update of level,rarity,base_atk,base_hp,bonus_atk,bonus_hp,attack_growth,hp_growth on player_heroes for each row execute function ensure_pvp_hero_stats();
update player_heroes set hero_template_id=coalesce(hero_template_id,hero_key,name),base_atk=base_atk where base_atk is null or base_hp is null or attack_growth is null or hp_growth is null or final_atk is null or final_hp is null;
alter table player_heroes alter column base_atk set not null,alter column base_hp set not null,alter column attack_growth set not null,alter column hp_growth set not null,alter column final_atk set not null,alter column final_hp set not null,alter column archetype set not null,alter column stats_seed set not null;
alter table player_heroes add constraint player_heroes_pvp_positive check(base_atk>0 and base_hp>0 and final_atk>0 and final_hp>0),add constraint player_heroes_archetype_check check(archetype in('warrior','assassin','tank','mage','archer','support'));

create table pvp_team_slots(id uuid primary key default gen_random_uuid(),user_id uuid not null references game_players(id) on delete cascade,team_type text not null check(team_type in('attack','defense')),slot integer not null check(slot between 1 and 5),hero_id uuid not null references player_heroes(id) on delete cascade,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(user_id,team_type,slot),unique(user_id,team_type,hero_id));
create index pvp_team_slots_user_idx on pvp_team_slots(user_id,team_type);
create table pvp_battles(id uuid primary key default gen_random_uuid(),attacker_id uuid not null references game_players(id),defender_id uuid not null references game_players(id),attacker_team_snapshot jsonb not null,defender_team_snapshot jsonb not null,battle_log jsonb not null default '[]',winner_id uuid references game_players(id),result text not null check(result in('attacker_win','defender_win')),total_turns integer not null check(total_turns between 1 and 50),attacker_power integer not null,defender_power integer not null,reward_fc numeric not null default 0,trophy_change integer not null default 0,created_at timestamptz not null default now(),completed_at timestamptz not null default now());
create index pvp_battles_attacker_idx on pvp_battles(attacker_id,created_at desc);create index pvp_battles_defender_idx on pvp_battles(defender_id,created_at desc);
create or replace function public.clean_pvp_battle_log()returns trigger language plpgsql as $$begin select coalesce(jsonb_agg(x),'[]')into new.battle_log from jsonb_array_elements(new.battle_log)x where x?'turn';return new;end$$;create trigger pvp_battle_log_clean before insert on pvp_battles for each row execute function clean_pvp_battle_log();
create table pvp_opponent_impressions(user_id uuid not null references game_players(id) on delete cascade,opponent_id uuid not null references game_players(id) on delete cascade,last_shown_at timestamptz not null default now(),shown_count integer not null default 1,primary key(user_id,opponent_id));
alter table pvp_team_slots enable row level security;alter table pvp_battles enable row level security;alter table pvp_opponent_impressions enable row level security;revoke all on pvp_team_slots,pvp_battles,pvp_opponent_impressions from anon,authenticated;

create or replace function public.pvp_hero_json(h player_heroes) returns jsonb language sql stable as $$select jsonb_build_object('heroId',h.id,'name',h.name,'imageUrl',h.image,'rarity',normalize_hero_rarity(h.rarity),'level',h.level,'archetype',h.archetype,'finalAtk',h.final_atk,'finalHp',h.final_hp,'defense',0,'speed',h.level,'power',round(h.final_atk*2.2+h.final_hp*.18+h.level*25))$$;
create or replace function public.pvp_team_json(p_user uuid,p_type text) returns jsonb language sql stable as $$select coalesce(jsonb_agg(pvp_hero_json(h)||jsonb_build_object('slot',s.slot) order by s.slot),'[]') from pvp_team_slots s join player_heroes h on h.id=s.hero_id where s.user_id=p_user and s.team_type=p_type$$;
create or replace function public.pvp_team_power(p_user uuid,p_type text) returns integer language sql stable as $$select coalesce(sum(round(h.final_atk*2.2+h.final_hp*.18+h.level*25)),0)::int from pvp_team_slots s join player_heroes h on h.id=s.hero_id where s.user_id=p_user and s.team_type=p_type$$;
create or replace function public.pvp_league(t integer) returns text language sql immutable as $$select case when t>=2500 then 'Lendária' when t>=2000 then 'Diamante' when t>=1600 then 'Platina' when t>=1200 then 'Ouro' when t>=800 then 'Prata' else 'Bronze' end$$;

create or replace function public.get_pvp_dashboard(p_telegram_id bigint) returns jsonb language plpgsql security definer set search_path=public as $$declare u game_players%rowtype;begin select * into u from game_players where telegram_id=p_telegram_id;if u.id is null then raise exception 'PLAYER_NOT_FOUND';end if;return jsonb_build_object('userId',u.id,'trophies',u.pvp_trophies,'league',pvp_league(u.pvp_trophies),'tickets',u.pvp_tickets,'wins',u.pvp_wins,'losses',u.pvp_losses,'attackTeam',pvp_team_json(u.id,'attack'),'defenseTeam',pvp_team_json(u.id,'defense'),'teamPower',pvp_team_power(u.id,'attack'),'ownedHeroes',(select coalesce(jsonb_agg(pvp_hero_json(h) order by h.created_at),'[]') from player_heroes h where h.user_id=u.id),'history',(select coalesce(jsonb_agg(jsonb_build_object('id',b.id,'opponentName',coalesce(o.display_name,'Jogador'),'result',case when b.winner_id=u.id then 'win' else 'loss' end,'turns',b.total_turns,'trophyChange',case when b.attacker_id=u.id then b.trophy_change else -b.trophy_change end,'rewardFc',case when b.attacker_id=u.id then b.reward_fc else 0 end,'createdAt',b.created_at) order by b.created_at desc),'[]') from(select * from pvp_battles where attacker_id=u.id or defender_id=u.id order by created_at desc limit 30)b join game_players o on o.id=case when b.attacker_id=u.id then b.defender_id else b.attacker_id end),'ranking',(select coalesce(jsonb_agg(x order by x.position),'[]') from(select row_number()over(order by pvp_trophies desc,pvp_wins desc)position,id,coalesce(display_name,'Jogador')name,avatar_url "avatarUrl",pvp_trophies trophies,pvp_league(pvp_trophies)league,pvp_wins wins from game_players where not pvp_banned order by pvp_trophies desc,pvp_wins desc limit 100)x));end$$;
create or replace function public.save_pvp_team_slot(p_telegram_id bigint,p_team_type text,p_slot integer,p_hero_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare u uuid;begin if p_team_type not in('attack','defense') or p_slot not between 1 and 5 then raise exception 'INVALID_TEAM_SLOT';end if;select id into u from game_players where telegram_id=p_telegram_id for update;if not exists(select 1 from player_heroes where id=p_hero_id and user_id=u) then raise exception 'HERO_NOT_OWNED';end if;delete from pvp_team_slots where user_id=u and team_type=p_team_type and hero_id=p_hero_id and slot<>p_slot;insert into pvp_team_slots(user_id,team_type,slot,hero_id) values(u,p_team_type,p_slot,p_hero_id) on conflict(user_id,team_type,slot) do update set hero_id=excluded.hero_id,updated_at=now();return get_pvp_dashboard(p_telegram_id);end$$;
create or replace function public.remove_pvp_team_slot(p_telegram_id bigint,p_team_type text,p_slot integer) returns jsonb language plpgsql security definer set search_path=public as $$declare u uuid;begin select id into u from game_players where telegram_id=p_telegram_id;delete from pvp_team_slots where user_id=u and team_type=p_team_type and slot=p_slot;return get_pvp_dashboard(p_telegram_id);end$$;

create or replace function public.search_pvp_opponents(p_telegram_id bigint) returns jsonb language plpgsql security definer set search_path=public as $$declare u game_players%rowtype;power int;power_pct numeric;trophy_range int;result jsonb;step int;begin select * into u from game_players where telegram_id=p_telegram_id;if u.id is null then raise exception 'PLAYER_NOT_FOUND';end if;power:=pvp_team_power(u.id,'attack');if power=0 then raise exception 'ATTACK_TEAM_EMPTY';end if;for step in 1..3 loop power_pct:=case step when 1 then .20 when 2 then .35 else .50 end;trophy_range:=case step when 1 then 150 when 2 then 300 else 500 end;select coalesce(jsonb_agg(row_data order by repeat_rank,power_gap,random_key),'[]') into result from(select p.id "userId",coalesce(p.display_name,'Jogador')name,p.avatar_url "avatarUrl",p.pvp_trophies trophies,pvp_league(p.pvp_trophies)league,pvp_team_power(p.id,'defense') "teamPower",p.pvp_wins wins,pvp_team_json(p.id,'defense') "defenseTeam",case when i.last_shown_at>now()-interval '24 hours' then 1 else 0 end repeat_rank,abs(pvp_team_power(p.id,'defense')-power)power_gap,hashtextextended(p.id::text||clock_timestamp()::date::text,0)random_key from game_players p left join pvp_opponent_impressions i on i.user_id=u.id and i.opponent_id=p.id where p.id<>u.id and not p.pvp_banned and pvp_team_power(p.id,'defense')>0 and abs(pvp_team_power(p.id,'defense')-power)<=greatest(1,power*power_pct) and abs(p.pvp_trophies-u.pvp_trophies)<=trophy_range order by repeat_rank,power_gap,random_key limit 3)row_data;if jsonb_array_length(result)>0 then insert into pvp_opponent_impressions(user_id,opponent_id,last_shown_at) select u.id,(x->>'userId')::uuid,now() from jsonb_array_elements(result)x on conflict(user_id,opponent_id)do update set last_shown_at=now(),shown_count=pvp_opponent_impressions.shown_count+1;return jsonb_build_object('opponents',result);end if;end loop;return jsonb_build_object('opponents','[]'::jsonb);end$$;

create or replace function public.simulate_pvp_battle(a jsonb,d jsonb,seed text) returns jsonb language plpgsql security definer set search_path=public as $$declare ast jsonb;dst jsonb;initiative jsonb;entry jsonb;actor jsonb;target jsonb;side text;target_id text;raw numeric;reduction numeric;variance numeric;damage int;new_hp int;turn int:=0;winner text;alive_a boolean;alive_d boolean;hp_a numeric;hp_d numeric;begin select coalesce(jsonb_agg(x||jsonb_build_object('currentHp',(x->>'finalHp')::int)),'[]')into ast from jsonb_array_elements(a)x;select coalesce(jsonb_agg(x||jsonb_build_object('currentHp',(x->>'finalHp')::int)),'[]')into dst from jsonb_array_elements(d)x;select jsonb_agg(jsonb_build_object('side',side,'heroId',hero_id)order by speed desc,level desc,tie)into initiative from(select'attacker'side,x->>'heroId'hero_id,coalesce((x->>'speed')::int,(x->>'level')::int)speed,(x->>'level')::int level,hashtextextended(seed||x->>'heroId',0)tie from jsonb_array_elements(a)x union all select'defender',x->>'heroId',coalesce((x->>'speed')::int,(x->>'level')::int),(x->>'level')::int,hashtextextended(seed||x->>'heroId',0)from jsonb_array_elements(d)x)q;for turn in 1..50 loop entry:=initiative->((turn-1)%jsonb_array_length(initiative));side:=entry->>'side';if side='attacker'then select x into actor from jsonb_array_elements(ast)x where x->>'heroId'=entry->>'heroId'and(x->>'currentHp')::int>0;select x into target from jsonb_array_elements(dst)x where(x->>'currentHp')::int>0 order by(x->>'currentHp')::numeric/greatest(1,(x->>'finalHp')::numeric),hashtextextended(seed||turn::text||x->>'heroId',0)limit 1;else select x into actor from jsonb_array_elements(dst)x where x->>'heroId'=entry->>'heroId'and(x->>'currentHp')::int>0;select x into target from jsonb_array_elements(ast)x where(x->>'currentHp')::int>0 order by(x->>'currentHp')::numeric/greatest(1,(x->>'finalHp')::numeric),hashtextextended(seed||turn::text||x->>'heroId',0)limit 1;end if;if actor is null or target is null then actor:=null;continue;end if;raw:=(actor->>'finalAtk')::numeric;reduction:=coalesce((target->>'defense')::numeric,0)/(coalesce((target->>'defense')::numeric,0)+300);variance:=.95+pvp_stat_unit(seed||':'||turn||':damage')*.10;damage:=greatest(1,round(raw*(1-reduction)*variance));new_hp:=greatest(0,(target->>'currentHp')::int-damage);target_id:=target->>'heroId';if side='attacker'then select jsonb_agg(case when x->>'heroId'=target_id then x||jsonb_build_object('currentHp',new_hp)else x end)into dst from jsonb_array_elements(dst)x;else select jsonb_agg(case when x->>'heroId'=target_id then x||jsonb_build_object('currentHp',new_hp)else x end)into ast from jsonb_array_elements(ast)x;end if;a:=coalesce(a,'[]')||jsonb_build_array(jsonb_build_object('turn',turn,'side',side,'attackerId',actor->>'heroId','targetId',target_id,'damage',damage,'remainingHp',new_hp));select exists(select 1 from jsonb_array_elements(ast)x where(x->>'currentHp')::int>0),exists(select 1 from jsonb_array_elements(dst)x where(x->>'currentHp')::int>0)into alive_a,alive_d;if not alive_d then winner:='attacker';exit;elsif not alive_a then winner:='defender';exit;end if;end loop;if winner is null then select coalesce(sum((x->>'currentHp')::numeric)/greatest(1,(x->>'finalHp')::numeric),0)into hp_a from jsonb_array_elements(ast)x;select coalesce(sum((x->>'currentHp')::numeric)/greatest(1,(x->>'finalHp')::numeric),0)into hp_d from jsonb_array_elements(dst)x;winner:=case when hp_a>hp_d then'attacker'else'defender'end;end if;return jsonb_build_object('attackerState',ast,'defenderState',dst,'battleLog',a,'winnerSide',winner,'turns',turn);end$$;

create or replace function public.start_pvp_battle(p_telegram_id bigint,p_opponent_id uuid) returns jsonb language plpgsql security definer set search_path=public as $$declare attacker game_players%rowtype;defender game_players%rowtype;atk jsonb;def jsonb;sim jsonb;battle_id uuid;winner uuid;result text;change int;reward numeric:=0;seed text;begin select * into attacker from game_players where telegram_id=p_telegram_id;if attacker.id is null then raise exception 'PLAYER_NOT_FOUND';end if;if attacker.id=p_opponent_id then raise exception 'INVALID_OPPONENT';end if;perform 1 from game_players where id in(attacker.id,p_opponent_id)order by id for update;select * into attacker from game_players where id=attacker.id;select * into defender from game_players where id=p_opponent_id;if defender.id is null or defender.pvp_banned then raise exception 'OPPONENT_UNAVAILABLE';end if;if attacker.pvp_tickets<1 then raise exception 'NO_PVP_TICKETS';end if;if exists(select 1 from pvp_battles where attacker_id=attacker.id and defender_id=defender.id and created_at>clock_timestamp()-interval'3 seconds')then raise exception 'BATTLE_ALREADY_STARTED';end if;atk:=pvp_team_json(attacker.id,'attack');def:=pvp_team_json(defender.id,'defense');if jsonb_array_length(atk)=0 then raise exception 'ATTACK_TEAM_EMPTY';end if;if jsonb_array_length(def)=0 then raise exception 'INVALID_DEFENSE_TEAM';end if;update game_players set pvp_tickets=pvp_tickets-1 where id=attacker.id;seed:=gen_random_uuid()::text;sim:=simulate_pvp_battle(atk,def,seed);if sim->>'winnerSide'='attacker'then winner:=attacker.id;result:='attacker_win';change:=25;reward:=2500;update game_players set pvp_trophies=pvp_trophies+25,pvp_wins=pvp_wins+1,forge_coins=forge_coins+reward,updated_at=now()where id=attacker.id;update game_players set pvp_trophies=greatest(0,pvp_trophies-15),pvp_losses=pvp_losses+1,updated_at=now()where id=defender.id;else winner:=defender.id;result:='defender_win';change:=-15;update game_players set pvp_trophies=greatest(0,pvp_trophies-15),pvp_losses=pvp_losses+1,updated_at=now()where id=attacker.id;update game_players set pvp_trophies=pvp_trophies+15,pvp_wins=pvp_wins+1,updated_at=now()where id=defender.id;end if;insert into pvp_battles(attacker_id,defender_id,attacker_team_snapshot,defender_team_snapshot,battle_log,winner_id,result,total_turns,attacker_power,defender_power,reward_fc,trophy_change)values(attacker.id,defender.id,jsonb_build_object('heroes',atk,'pet',get_pet_pvp_snapshot(attacker.id)),jsonb_build_object('heroes',def,'pet',get_pet_pvp_snapshot(defender.id)),sim->'battleLog',winner,result,(sim->>'turns')::int,pvp_team_power(attacker.id,'attack'),pvp_team_power(defender.id,'defense'),reward,change)returning id into battle_id;return jsonb_build_object('battleId',battle_id,'result',result,'winnerId',winner,'totalTurns',(sim->>'turns')::int,'rewardFc',reward,'trophyChange',change,'battleLog',sim->'battleLog','attackerState',sim->'attackerState','defenderState',sim->'defenderState');end$$;
create or replace function public.generate_missing_hero_stats()returns integer language plpgsql security definer set search_path=public as $$declare affected integer;begin update player_heroes set base_atk=base_atk where base_atk is null or base_hp is null or attack_growth is null or hp_growth is null or final_atk is null or final_hp is null;get diagnostics affected=row_count;return affected;end$$;
create or replace function public.get_pvp_history(p_telegram_id bigint)returns jsonb language sql security definer set search_path=public as $$select coalesce(get_pvp_dashboard(p_telegram_id)->'history','[]')$$;
create or replace function public.get_pvp_ranking()returns jsonb language sql security definer set search_path=public as $$select coalesce(jsonb_agg(x order by x.position),'[]')from(select row_number()over(order by pvp_trophies desc,pvp_wins desc)position,id,coalesce(display_name,'Jogador')name,avatar_url "avatarUrl",pvp_trophies trophies,pvp_league(pvp_trophies)league,pvp_wins wins from game_players where not pvp_banned order by pvp_trophies desc,pvp_wins desc limit 100)x$$;
grant execute on function get_pvp_dashboard(bigint),save_pvp_team_slot(bigint,text,integer,uuid),remove_pvp_team_slot(bigint,text,integer),search_pvp_opponents(bigint),start_pvp_battle(bigint,uuid),generate_missing_hero_stats(),get_pvp_history(bigint),get_pvp_ranking()to service_role;
